// The envelope posted by examples/integrations/wake_webhook_json.py.
// n8n puts the POST body under json.body on most webhook configs; handle both.
const b = $input.first().json.body ?? $input.first().json;
return [{ json: {
  ts: b.ts ?? null,
  module: b.winner?.module ?? null,
  salience: b.winner?.salience ?? null,
  thought_type: b.winner?.thought_type ?? null,
  trigger_count: b.winner?.trigger_count ?? null,
  briefing: b.briefing ?? ""
}}];
